package jp.schoolboard;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;
public class Reminder extends BroadcastReceiver {
 static void schedule(Context c){int hour=Store.p(c).getInt("hour",20),minute=Store.p(c).getInt("minute",0);ZonedDateTime now=ZonedDateTime.now(),next=now.withHour(hour).withMinute(minute).withSecond(0).withNano(0);if(!next.isAfter(now))next=next.plusDays(1);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.toInstant().toEpochMilli(),PendingIntent.getBroadcast(c,0,new Intent(c,Reminder.class).setAction("daily"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}
 public void onReceive(Context c,Intent i){if("daily".equals(i.getAction())){String today=LocalDate.now().toString();if(!today.equals(Store.p(c).getString("notified",""))){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("daily","提出物の確認",NotificationManager.IMPORTANCE_DEFAULT));String text="提出物の登録忘れはありませんか？";java.util.List<org.json.JSONObject> tasks=Store.pending(c);if(!tasks.isEmpty())text="未提出 "+tasks.size()+"件・最も近い期限 "+tasks.get(0).optString("due")+"。登録忘れも確認しよう。";try{n.notify(1,new Notification.Builder(c,"daily").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("今日の提出物チェック").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(BoardWidget.open(c,false)).setAutoCancel(true).build());Store.p(c).edit().putString("notified",today).apply();}catch(SecurityException ignored){}}}BoardWidget.refresh(c);schedule(c);}
}